  "test_metrics_accessed": false,
  "validation_only": true,
  "steps": [
    {
      "id": "step-1-inspect",
      "action": "inspect_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": [],
      "expected_artifacts": ["dataset_summary"]
    },
    {
      "id": "step-2-validate",
      "action": "validate_dataset",
      "arguments": {
        "manifest_path": "data/processed/formal_v3/dataset_manifest.json"
      },
      "depends_on": ["step-1-inspect"],
      "expected_artifacts": ["validation_report"]
    },
    {
      "id": "step-3-list-markets",
      "action": "list_markets",
      "arguments": {},
      "depends_on": [],
      "expected_artifacts": ["market_list"]
    },
    {
      "id": "step-4-list-symbols",
      "action": "list_symbols",
      "arguments": {
        "markets": ["CN", "HK", "JP", "US"]
      },
      "depends_on": ["step-3-list-markets"],
      "expected_artifacts": ["symbol_map"]
    },
    {
      "id": "step-5-create-split",
      "action": "create_split",
      "arguments": {
        "protocol": "Phase12",
