      "expected_artifacts": ["split_manifest"]
    },
    {
      "id": "step-6-validate-config",
      "action": "validate_experiment_config",
      "arguments": {
        "split_manifest": "step-5-create-split.split_manifest"
      },
      "depends_on": ["step-5-create-split"],
      "expected_artifacts": ["config_validation_report"]
    },
    {
      "id": "step-7-estimate-budget",
